Q: display html page with node.js A: <p>I'm very late but I feel like leaving a comment here.</p>
<p>The reason it only sees .html is because your server sends .html on any request. The browser tries to fetch anything that HTML asks, by sending another request to the server but with URL appended with /your-requested-file.extension. So  basically it gets same file trying to get css, js, image files, etc. To make it work you can add very basic &quot;routes&quot; to get .css and .js files.<br />
Note the header's content-type is different for each</p>
<p>So, a hardcoded solution for this, assuming that your /var/nodeFiles/www/ has style.css and index.js attempted to be fetched, and your front end just does rel=&quot;style.css&quot; and for script src=&quot;index.js&quot; for learning purposes will be:</p>
<pre><code>var http = require('http'),
fs = require('fs');

let g_html;
let g_css;
let g_js;

// Read html, css, js, files and write them into variables i made right above this text
fs.readFile('/var/nodeFiles/www/index.html', function (err, html) {     
    // Set global html variable
    g_html = html
});
fs.readFile('/var/nodeFiles/www/style.css', function (err, css) {
    // Set global html variable
    g_css = css;
});
fs.readFile('/var/nodeFiles/www/index.js', function (err, js) {
    // Set global html variable
    g_js = js;
});

http.createServer(function(request, response) {  
    const url = request.url;

    if(url === style.css)
    {
        response.writeHeader(200, {&quot;Content-Type&quot;: &quot;text/css&quot;});  
        response.write(g_css);
        response.end();    
    }
    else if(url === index.js)
    {
        response.writeHeader(200, {&quot;Content-Type&quot;: &quot;text/js&quot;});  
        response.write(g_js);  
        response.end();  
    }
    else{
        // if url is any, including just emptiness, return HTML
        response.writeHeader(200, {&quot;Content-Type&quot;: &quot;text/html&quot;});  
        response.write(g_html);  
        response.end(); 
    }

}).listen(80);
</code></pre>
<p>Some frameworks do this programmatically by analyzing your folder structure and doing basically this. Making an endpoint for each file and being called same as the file itself.</p>
